def fig_air():
    names=['Сыртқы\nауа','Сүзгі','Қыздырғыш','Желдеткіш','Бөлме'];w=58;g=10;o=''
    for i,t in enumerate(names):
        x=5+i*(w+g);o+=R(x,50,w,44,'bxa' if i==3 else 'bx',4)
        for j,l in enumerate(t.split('\n')):o+=f'<text x="{x+w/2}" y="{72+(j-(len(t.split(chr(10)))-1)/2)*13+4}" text-anchor="middle" style="font-size:10px">{l}</text>'
        if i<4:o+=A(x+w,72,x+w+g,72)
    for i,v in ((0,'−5,0 °C'),(2,'21,0 °C'),(4,'22,4 °C')):o+=T(5+i*(w+g)+w/2,114,v,'t-s t-b')
    ax=5+3*(w+g)+w/2;o+=f'<circle cx="{ax}" cy="30" r="12" class="bxa"/>'+T(ax,35,'!','t-s t-b')+LN(f'M{ax} 42 L{ax} 50','ln')
    o+=T(170,150,'ауа жолы солдан оңға; температура — өз нүктесінде,','t-s mu')+T(170,165,'авария белгісі — жабдықтың жанында (мәндер мысал үшін)','t-s mu')
    return S(340,176,o,'Желдету экраны: сыртқы ауа, сүзгі, қыздырғыш, желдеткіш, бөлме; температуралар өз нүктелерінде, авария белгісі желдеткіштің жанында')
f_air=F(fig_air(),'Желдету экраны (жеңілдетілген сұлба): технология бағытымен солдан оңға')

